let age = 18;
console.log(age + 1); // 19
age = "十八岁";
console.log(age);     // 十八岁

const userName = "小林";
console.log(userName); // 小林
// userName = "小陈";  // 如果执行，会因重新赋值 const 绑定而报错

const student = "小林";
const code = "0018";
const greeting = `你好，${student}`;
console.log(greeting);        // 你好，小林
console.log(code + 1);        // 00181：文本拼接
console.log(student.replace("林", "陈")); // 小陈
console.log(student);         // 小林：原字符串没被修改

const stock = 3;
const canBuy = stock > 0;
console.log(canBuy);        // true
if (canBuy) console.log("可以购买");
console.log(Boolean("false")); // true：这是一段非空文字
console.log(Boolean([]));      // true：空数组也是对象
console.log(Boolean(""));      // false：空字符串

let nickname;
const profile = {};
function sayHi() { console.log("你好"); }
console.log(nickname);        // undefined
console.log(profile.avatar);  // undefined
const result = sayHi();       // 先输出 你好
console.log(result);          // undefined：函数没有 return
// console.log(notDeclared);  // 若执行，会报 ReferenceError

let selectedProduct = null;
if (selectedProduct === null) console.log("请先选择商品");
selectedProduct = { name: "笔记本" };
console.log(selectedProduct.name); // 笔记本
selectedProduct = null;            // 用户取消选择
console.log(selectedProduct?.name ?? "未选择"); // 未选择

const largeId = BigInt("9007199254740993");
console.log(largeId + 1n); // 9007199254740994n
console.log(5n / 2n);      // 2n：整数除法
// console.log(largeId + 1); // 会报错，不能混合算术
console.log(String(largeId)); // 9007199254740993

const tagA = Symbol("内部标记");
const tagB = Symbol("内部标记");
console.log(tagA === tagB); // false
const item = { name: "书", [tagA]: "来自模块 A" };
item[tagB] = "来自模块 B";
console.log(item[tagA]); // 来自模块 A
console.log(item[tagB]); // 来自模块 B

const user = { name: "小林", age: 18 };
console.log(user.name); // 小林
user.age = 19;
const cart = [{ name: "书", quantity: 2 }];
console.log(cart[0].quantity); // 2：数组从下标 0 开始
function double(value) { return value * 2; }
console.log(double(user.age)); // 38

let first = 10;
let second = first;
second = 20;
console.log(first); // 10

const a = { score: 10 };
const b = a;
b.score = 20;
console.log(a.score); // 20：两个名字访问同一个对象

const input = "2";
const quantity = Number(input);
const valid = Number.isInteger(quantity) && quantity > 0;
console.log(input + 1);    // 21：原输入仍是字符串
console.log(quantity + 1); // 3：转换后的数字
console.log(valid);        // true
console.log(typeof quantity); // number
console.log(Array.isArray([quantity])); // true

function readQuantity(raw) {
  if (typeof raw !== "string") return null;
  const text = raw.trim();
  if (!/^\d+$/.test(text)) return null;
  const quantity = Number(text);
  return Number.isSafeInteger(quantity) && quantity >= 1 && quantity <= 99
    ? quantity
    : null;
}

console.log(readQuantity(" 2 ")); // 2
console.log(readQuantity(""));    // null
console.log(readQuantity("2件")); // null
console.log(readQuantity("100")); // null

const cartItem = {
  productId: "0018",
  name: "笔记本",
  priceCents: 1200,
  quantity: 2,
  loggedIn: true,
  coupon: null
};
const totalCents = cartItem.priceCents * cartItem.quantity;
const canSubmit = cartItem.loggedIn && cartItem.quantity > 0;
console.log(totalCents); // 2400
console.log(canSubmit);  // true
console.log(`${cartItem.name} × ${cartItem.quantity}`); // 笔记本 × 2
